WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM sessions) SELECT *, SUM(is_new_session) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps;
